	display: grid;
	grid-template-columns: minmax(80px, 1fr) minmax(0, 3fr);
	gap: 12px;
}
.search-preview dd {
	margin: 0;
}
.search-preview img {
	max-width: 100%;
}
.search-preview p {
	white-space: pre-wrap;
}
@keyframes search-arrive {
	from {
		opacity: 0.6;
		transform: translateY(5px);
	}
	to {
		opacity: 1;
		transform: translateY(0);
	}
