.search-page {
	animation: search-arrive 140ms cubic-bezier(0.2, 0.7, 0.3, 1) both;
}
@media (max-width: 700px) {
	.search-page {
		padding: 20px 16px;
	}
	.search-family-brand {
		grid-template-columns: 1fr;
		gap: 20px;
	}
	.search-brand-rail {
		min-height: auto;
		padding: 20px;
	}
	.search-brand-rail strong {
		font-size: 28px;
		margin: 12px 0;
	}
	.search-brand-mark {
		display: none;
	}

	.search-family-technology .search-core {
		padding: 16px;
	}
	.search-preview {
		padding: 20px 16px;
	}
	.search-global {
